package ktanesolver.module.modded.regular.reorderedkeys;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.reorderedkeys.ReorderedKeysInput.*;
class ReorderedKeysSolverTest{@Test void decodesPivotAndSubmitsAlreadyCorrectConfiguration(){List<Key>keys=List.of(new Key(Color.RED,3,Color.GREEN),new Key(Color.RED,4,Color.GREEN),new Key(Color.RED,2,Color.GREEN),new Key(Color.RED,3,Color.GREEN),new Key(Color.RED,2,Color.GREEN),new Key(Color.RED,5,Color.GREEN));ModuleEntity module=new ModuleEntity();var result=(SolveSuccess<ReorderedKeysOutput>)new ReorderedKeysSolver().solve(new RoundEntity(),new BombEntity(),module,new ReorderedKeysInput(1,keys));assertThat(result.output().values()).containsExactly(1,2,3,4,5,6);assertThat(result.output().pivot()).isEqualTo(4);assertThat(result.output().swaps()).isEmpty();assertThat(result.output().twitchCommand()).isEqualTo("press 4");assertThat(module.getState()).containsKey("reorderedKeysStage1");}}
